  "me.langs": { en: "Languages you speak", uk: "Мови, якими ти говориш", najdi: "اللغات اللي تتكلمها", msa: "اللغات التي تتحدثها" },
  "me.hobbies": { en: "What you like", uk: "Що ти любиш", najdi: "وش تحب", msa: "ما تحبّ" },
  "me.intro": { en: "Your introduction", uk: "Твоя розповідь про себе", najdi: "تعريفك بنفسك", msa: "تعريفك بنفسك" },
  "me.qa": { en: "What they'll ask you — and your answers", uk: "Що тебе спитають — і твої відповіді", najdi: "وش بيسألونك — وأجوبتك", msa: "ما سيسألونك عنه — وإجاباتك" },
  "me.askHer": { en: "Ask her back", uk: "Спитай її у відповідь", najdi: "اسألها بعد", msa: "اسألها أنت أيضًا" },
  "path.title": { en: "Your path", uk: "Твій шлях", najdi: "طريقك", msa: "مسارك" },
  "path.sub": { en: "From Day 1 to A1 on 21 December and A2 by 9 February — one week at a time. Do the steps in order.", uk: "Від першого дня до A1 21 грудня і A2 до 9 лютого — тиждень за тижнем. Роби кроки по черзі.", najdi: "من أول يوم لين A1 يوم ٢١ ديسمبر، وA2 قبل ٩ فبراير — أسبوع بأسبوع. سوّ الخطوات بالترتيب.", msa: "من اليوم الأول حتى A1 في ٢١ ديسمبر، وA2 قبل ٩ فبراير — أسبوعًا بأسبوع. أنجز الخطوات بالترتيب." },
  "path.subTeacher": { en: "Volodymyr's route to A1 and A2, one week at a time — what he reads, practises and says to you each week.", uk: "Шлях Володимира до A1 і A2, тиждень за тижнем — що він читає, тренує і каже тобі щотижня.", najdi: "طريق فولوديمير لـA1 وA2، أسبوع بأسبوع — وش يقرا ويتدرب عليه ووش يقول لك كل أسبوع.", msa: "مسار فولوديمير إلى A1 وA2، أسبوعًا بأسبوع — ما يقرؤه ويتدرّب عليه وما يقوله لكِ كل أسبوع." },
  "path.weekOf": { en: "week of {total}", uk: "тиждень із {total}", najdi: "أسبوع من {total}", msa: "أسبوع من {total}" },
  "path.toA1": { en: "days to A1 (21 Dec)", uk: "днів до A1 (21 грудня)", najdi: "يوم لين A1 (٢١ ديسمبر)", msa: "يومًا حتى A1 (٢١ ديسمبر)" },
  "path.toA2": { en: "days to A2 (9 Feb)", uk: "днів до A2 (9 лютого)", najdi: "يوم لين A2 (٩ فبراير)", msa: "يومًا حتى A2 (٩ فبراير)" },
  "path.steps": { en: "steps done", uk: "кроків зроблено", najdi: "خطوة خلصت", msa: "خطوة منجزة" },
  "path.how": { en: "Open this week and go down the list. Stories, chats and practice tick themselves; tick the rest when you've done them. Behind? Just carry on from where you are.", uk: "Відкрий цей тиждень і йди списком. Історії, чати й вправи позначаються самі; решту познач, коли зробиш. Відстаєш? Просто продовжуй з того місця, де ти є.", najdi: "افتح هالأسبوع وامش على القايمة. القصص والمحادثات والتدريب تنحط علامتها لحالها، والباقي حط عليه علامة لا خلصته. متأخر؟ كمّل من مكانك وبس.", msa: "افتح هذا الأسبوع وسِر على القائمة. القصص والمحادثات والتدريب تُعلَّم تلقائيًا، وعلّم الباقي حين تنجزه. متأخر؟ أكمل من حيث أنت." },
  "path.now": { en: "this week", uk: "цей тиждень", najdi: "هالأسبوع", msa: "هذا الأسبوع" },
  "path.auto": { en: "Ticks itself when you've done it", uk: "Позначається само, коли зробиш", najdi: "تنحط علامتها لحالها لا خلصتها", msa: "تُعلَّم تلقائيًا عند الإنجاز" },
  "path.tick": { en: "Mark as done", uk: "Позначити як зроблене", najdi: "خلصتها", msa: "تمّ الإنجاز" },
  "path.pass": { en: "score {n}%+", uk: "набери {n}%+", najdi: "جيب {n}% وفوق", msa: "{n}% فأكثر" },
